/**
 * Campaign results from the provider's own events, with honest uncertainty.
 * No React and no dependencies, so it runs anywhere: in the browser over a
 * live event log, or on the server over events from your warehouse.
 *
 * Rates are per exposure: an impression for a shown arm, a `holdout` event
 * for the kept-out group (both counted once per page view).
 */
import type { PromotionEvent } from './promotion-provider'

export type Metric = 'click' | 'convert'

export type ArmStats = {
  /** `control`, a variant id, `holdout`, or `all` for a record without arms. */
  arm: string
  exposures: number
  clicks: number
  conversions: number
  dismissals: number
  /** Successes for the chosen metric over exposures; 0 with no exposures. */
  rate: number
  /** 95% Wilson interval for `rate`. */
  interval: [number, number]
}

export type Verdict = 'better' | 'worse' | 'unclear' | 'not-enough-data'

export type Comparison = {
  arm: string
  against: string
  /** Difference in rates, arm minus baseline (percentage points / 100). */
  difference: number
  /** Relative change against the baseline rate; null when that is 0. */
  relative: number | null
  /** 95% interval for `difference`. */
  interval: [number, number]
  /** Two-sided p-value of a two-proportion z-test. */
  pValue: number
  verdict: Verdict
  /** Rough exposures per arm still needed to call it, when not enough data. */
  moreNeeded: number | null
}

export type RecordStats = {
  id: string
  placement: PromotionEvent['placement']
  campaign?: string
  /** Control first, other arms by name, holdout last. */
  arms: ArmStats[]
  /** Each arm against control, and everyone shown against the holdout. */
  comparisons: Comparison[]
}

const Z = 1.959964 // 95%
const Z_POWER = 0.841621 // 80% power

/** 95% Wilson score interval for `successes` of `n`. */
export function wilson(successes: number, n: number): [number, number] {
  if (n === 0) return [0, 0]
  const p = successes / n
  const z2 = Z * Z
  const center = (p + z2 / (2 * n)) / (1 + z2 / n)
  const half =
    (Z * Math.sqrt((p * (1 - p)) / n + z2 / (4 * n * n))) / (1 + z2 / n)
  // Exact at the extremes; floating point would leave 0.9999999999999999.
  return [
    successes === 0 ? 0 : Math.max(0, center - half),
    successes === n ? 1 : Math.min(1, center + half),
  ]
}

/** Standard normal CDF (Abramowitz and Stegun 7.1.26, error under 1.5e-7). */
function normalCdf(x: number): number {
  const t = 1 / (1 + 0.3275911 * (Math.abs(x) / Math.SQRT2))
  const poly =
    t *
    (0.254829592 +
      t *
        (-0.284496736 +
          t * (1.421413741 + t * (-1.453152027 + t * 1.061405429))))
  const erf = 1 - poly * Math.exp(-(x * x) / 2)
  return x >= 0 ? (1 + erf) / 2 : (1 - erf) / 2
}

/** The normal approximation holds once each arm has 5 successes and 5 failures. */
function enough(successes: number, n: number) {
  return successes >= 5 && n - successes >= 5
}

/** Compares `arm` with `base` on their rates. */
export function compare(
  arm: ArmStats,
  base: ArmStats,
  metric: Metric,
): Comparison {
  const s1 = metric === 'click' ? arm.clicks : arm.conversions
  const s2 = metric === 'click' ? base.clicks : base.conversions
  const n1 = arm.exposures
  const n2 = base.exposures
  const p1 = n1 ? s1 / n1 : 0
  const p2 = n2 ? s2 / n2 : 0
  const difference = p1 - p2
  const unpooled = Math.sqrt(
    (n1 ? (p1 * (1 - p1)) / n1 : 0) + (n2 ? (p2 * (1 - p2)) / n2 : 0),
  )
  // The test and the interval share one standard error, so a verdict can
  // never contradict the interval printed beside it (a pooled test and an
  // unpooled interval disagree near the boundary).
  const z = unpooled > 0 && n1 && n2 ? difference / unpooled : 0
  const pValue = z === 0 ? 1 : 2 * (1 - normalCdf(Math.abs(z)))
  const interval: [number, number] = [
    difference - Z * unpooled,
    difference + Z * unpooled,
  ]
  const ready = enough(s1, n1) && enough(s2, n2)
  const verdict: Verdict = !ready
    ? 'not-enough-data'
    : pValue < 0.05
      ? difference > 0
        ? 'better'
        : 'worse'
      : 'unclear'
  let moreNeeded: number | null = null
  if (verdict === 'not-enough-data' || verdict === 'unclear') {
    // Exposures per arm to detect the observed difference (or a 20% relative
    // change when there is none yet) at 95% confidence and 80% power.
    const baseRate = p2 || p1 || 0
    const target = Math.abs(difference) || baseRate * 0.2
    if (target > 0 && baseRate > 0 && baseRate < 1) {
      const variance =
        p1 * (1 - p1) + p2 * (1 - p2) || 2 * baseRate * (1 - baseRate)
      const perArm = Math.ceil(((Z + Z_POWER) ** 2 * variance) / target ** 2)
      moreNeeded = Math.max(0, perArm - Math.min(n1, n2))
    }
  }
  return {
    arm: arm.arm,
    against: base.arm,
    difference,
    relative: p2 > 0 ? difference / p2 : null,
    interval,
    pValue,
    verdict,
    moreNeeded,
  }
}

function emptyArm(arm: string): ArmStats {
  return {
    arm,
    exposures: 0,
    clicks: 0,
    conversions: 0,
    dismissals: 0,
    rate: 0,
    interval: [0, 0],
  }
}

function armOrder(a: string, b: string) {
  const rank = (arm: string) =>
    arm === 'control' ? 0 : arm === 'holdout' ? 2 : 1
  return rank(a) - rank(b) || a.localeCompare(b)
}

/** Per-record arms and comparisons from a list of provider events. */
export function campaignStats(
  events: readonly PromotionEvent[],
  { metric = 'convert' }: { metric?: Metric } = {},
): RecordStats[] {
  const records = new Map<
    string,
    {
      placement: PromotionEvent['placement']
      campaign?: string
      arms: Map<string, ArmStats>
    }
  >()
  for (const event of events) {
    let record = records.get(event.id)
    if (!record) {
      record = {
        placement: event.placement,
        campaign: event.campaign,
        arms: new Map(),
      }
      records.set(event.id, record)
    }
    const name = event.type === 'holdout' ? 'holdout' : (event.variant ?? 'all')
    const arm = record.arms.get(name) ?? emptyArm(name)
    record.arms.set(name, arm)
    if (event.type === 'impression' || event.type === 'holdout')
      arm.exposures += 1
    else if (event.type === 'click') arm.clicks += 1
    else if (event.type === 'convert') arm.conversions += 1
    else if (event.type === 'dismiss') arm.dismissals += 1
  }

  return [...records].map(([id, record]) => {
    const arms = [...record.arms.values()]
      .filter((arm) => arm.exposures > 0 || arm.conversions > 0)
      .sort((a, b) => armOrder(a.arm, b.arm))
    for (const arm of arms) {
      const successes = metric === 'click' ? arm.clicks : arm.conversions
      // A conversion can come from a visitor exposed on another page view;
      // never report a rate above 100%.
      const capped = Math.min(successes, arm.exposures)
      arm.rate = arm.exposures ? capped / arm.exposures : 0
      arm.interval = wilson(capped, arm.exposures)
    }
    const comparisons: Comparison[] = []
    const control = arms.find((arm) => arm.arm === 'control')
    if (control)
      for (const arm of arms)
        if (arm.arm !== 'control' && arm.arm !== 'holdout')
          comparisons.push(compare(arm, control, metric))
    const holdout = arms.find((arm) => arm.arm === 'holdout')
    if (holdout) {
      const shown = arms.filter((arm) => arm.arm !== 'holdout')
      const all = shown.reduce<ArmStats>(
        (sum, arm) => ({
          ...sum,
          exposures: sum.exposures + arm.exposures,
          clicks: sum.clicks + arm.clicks,
          conversions: sum.conversions + arm.conversions,
          dismissals: sum.dismissals + arm.dismissals,
        }),
        emptyArm('shown'),
      )
      if (all.exposures) comparisons.push(compare(all, holdout, metric))
    }
    return {
      id,
      placement: record.placement,
      campaign: record.campaign,
      arms,
      comparisons,
    }
  })
}

'use client'

import * as React from 'react'
import {
  IconArrowDownRight,
  IconArrowUpRight,
  IconHourglass,
  IconMinus,
} from '@tabler/icons-react'
import { cn } from '@/lib/utils'

import type { Promotion } from './promotion'
import type { PromotionEvent } from './promotion-provider'
import {
  campaignStats,
  type ArmStats,
  type Comparison,
  type Metric,
  type RecordStats,
} from './campaign-stats'

const VERDICT = {
  better: { icon: IconArrowUpRight, label: 'Better' },
  worse: { icon: IconArrowDownRight, label: 'Worse' },
  unclear: { icon: IconMinus, label: 'No clear difference yet' },
  'not-enough-data': { icon: IconHourglass, label: 'Not enough data yet' },
} as const

/**
 * What each campaign did, from the provider's own events: exposures, click
 * and conversion rates per arm with 95% intervals, and a plain verdict for
 * every arm against control and for showing it at all against the holdout.
 *
 * It never overstates: until each arm has enough outcomes the verdict is
 * "not enough data yet" with a rough count of what is still needed, and a
 * difference that could be chance says so. Numbers are always in text; the
 * bars (one scale, leader emphasised, interval as a thin line) only help
 * the eye.
 */
export function CampaignResults({
  events,
  promotions = [],
  locale,
  defaultMetric = 'convert',
  className,
}: {
  events: readonly PromotionEvent[]
  /** To show titles instead of ids. */
  promotions?: readonly Pick<Promotion, 'id' | 'title'>[]
  locale?: string
  defaultMetric?: Metric
  className?: string
}) {
  const [metric, setMetric] = React.useState<Metric>(defaultMetric)
  const stats = React.useMemo(
    () => campaignStats(events, { metric }),
    [events, metric],
  )
  const titles = new Map(promotions.map((p) => [p.id, p.title]))
  // One decimal always, so rates line up in their column (6.0% by 7.8%).
  const percent = new Intl.NumberFormat(locale, {
    style: 'percent',
    minimumFractionDigits: 1,
    maximumFractionDigits: 1,
  })
  const count = new Intl.NumberFormat(locale)

  return (
    <section
      aria-label="Campaign results"
      data-slot="campaign-results"
      className={cn('flex flex-col gap-6', className)}
    >
      {/* Filters live in one row above every result. */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <p className="text-muted-foreground text-sm">
          {stats.length
            ? `${stats.length} ${stats.length === 1 ? 'campaign' : 'campaigns'} measured`
            : 'No results yet'}
        </p>
        <div
          role="radiogroup"
          aria-label="Measure"
          className="bg-muted inline-flex rounded-lg p-0.5 text-sm"
        >
          {(['convert', 'click'] as const).map((value) => (
            <button
              key={value}
              type="button"
              role="radio"
              aria-checked={metric === value}
              onClick={() => setMetric(value)}
              className={cn(
                'focus-visible:ring-ring/50 rounded-md px-3 py-1 transition-[background-color,color] duration-150 outline-none focus-visible:ring-3',
                metric === value
                  ? 'bg-background text-foreground shadow-xs'
                  : // muted-foreground on the muted track is under 4.5:1 in light.
                    'text-foreground/70 hover:text-foreground',
              )}
            >
              {value === 'convert' ? 'Conversions' : 'Clicks'}
            </button>
          ))}
        </div>
      </div>

      {stats.length === 0 ? (
        <p className="text-muted-foreground max-w-prose text-sm text-pretty">
          Exposures, clicks and conversions appear here as visitors see your
          campaigns. Send the provider’s events here, or read them back from
          your analytics.
        </p>
      ) : (
        stats.map((record) => (
          <RecordResult
            key={record.id}
            record={record}
            title={titles.get(record.id) ?? record.id}
            metric={metric}
            percent={percent}
            count={count}
          />
        ))
      )}
    </section>
  )
}

function RecordResult({
  record,
  title,
  metric,
  percent,
  count,
}: {
  record: RecordStats
  title: string
  metric: Metric
  percent: Intl.NumberFormat
  count: Intl.NumberFormat
}) {
  const shown = record.arms.filter((arm) => arm.arm !== 'holdout')
  const exposures = shown.reduce((sum, arm) => sum + arm.exposures, 0)
  const clicks = shown.reduce((sum, arm) => sum + arm.clicks, 0)
  const conversions = shown.reduce((sum, arm) => sum + arm.conversions, 0)
  const rate = (n: number) => (exposures ? Math.min(1, n / exposures) : 0)
  // One scale for every bar in this record, with room for the intervals.
  const top = Math.max(0.01, ...record.arms.map((arm) => arm.interval[1]))
  const leader = [...shown].sort((a, b) => b.rate - a.rate)[0]?.arm
  const armLabel = (arm: string) =>
    arm === 'all'
      ? 'Everyone shown'
      : arm === 'holdout'
        ? 'Holdout (not shown)'
        : arm === 'shown'
          ? 'Everyone shown'
          : arm === 'control'
            ? 'Control'
            : arm.charAt(0).toUpperCase() + arm.slice(1)

  return (
    <article className="border-border/60 flex flex-col gap-5 rounded-xl border p-5">
      <header className="flex flex-wrap items-baseline justify-between gap-2">
        <h3 className="font-medium text-balance">{title}</h3>
        <span className="text-muted-foreground text-xs">
          {record.placement}
          {record.campaign ? ` · ${record.campaign}` : ''}
        </span>
      </header>

      <dl className="grid grid-cols-3 gap-4">
        {[
          ['Exposures', count.format(exposures)],
          ['Click rate', percent.format(rate(clicks))],
          ['Conversion rate', percent.format(rate(conversions))],
        ].map(([label, value]) => (
          <div key={label} className="flex flex-col gap-1">
            <dt className="text-muted-foreground text-xs">{label}</dt>
            <dd className="text-2xl font-medium tracking-tight">{value}</dd>
          </div>
        ))}
      </dl>

      <table className="w-full text-sm">
        <caption className="sr-only">
          {metric === 'convert' ? 'Conversion' : 'Click'} rate by arm, with 95%
          intervals
        </caption>
        <thead>
          <tr className="text-muted-foreground text-xs">
            <th scope="col" className="pb-2 text-start font-normal">
              Arm
            </th>
            <th scope="col" className="pb-2 text-end font-normal">
              Exposures
            </th>
            <th scope="col" className="pb-2 text-end font-normal">
              {metric === 'convert' ? 'Conversions' : 'Clicks'}
            </th>
            <th scope="col" className="ps-4 pb-2 text-start font-normal">
              Rate, 95% interval
            </th>
          </tr>
        </thead>
        <tbody>
          {record.arms.map((arm) => (
            <ArmRow
              key={arm.arm}
              arm={arm}
              label={armLabel(arm.arm)}
              lead={arm.arm === leader && shown.length > 1}
              top={top}
              metric={metric}
              percent={percent}
              count={count}
            />
          ))}
        </tbody>
      </table>

      {record.comparisons.length ? (
        <ul className="flex flex-col gap-2 text-sm">
          {record.comparisons.map((comparison) => (
            <VerdictLine
              key={`${comparison.arm}-${comparison.against}`}
              comparison={comparison}
              armLabel={armLabel}
              percent={percent}
              count={count}
            />
          ))}
        </ul>
      ) : null}
    </article>
  )
}

function ArmRow({
  arm,
  label,
  lead,
  top,
  metric,
  percent,
  count,
}: {
  arm: ArmStats
  label: string
  lead: boolean
  top: number
  metric: Metric
  percent: Intl.NumberFormat
  count: Intl.NumberFormat
}) {
  const at = (value: number) => `${Math.min(100, (value / top) * 100)}%`
  return (
    <tr className="border-border/60 border-t">
      <th scope="row" className="py-2.5 pe-3 text-start font-medium">
        {label}
      </th>
      <td className="py-2.5 text-end tabular-nums">
        {count.format(arm.exposures)}
      </td>
      <td className="py-2.5 text-end tabular-nums">
        {count.format(metric === 'convert' ? arm.conversions : arm.clicks)}
      </td>
      <td className="py-2.5 ps-4">
        <div className="flex items-center gap-3">
          <span className="w-28 shrink-0 tabular-nums">
            {percent.format(arm.rate)}
            <span className="text-muted-foreground text-xs">
              {' '}
              {percent.format(arm.interval[0])} to{' '}
              {percent.format(arm.interval[1])}
            </span>
          </span>
          {/* One scale per record; the leader carries the emphasis. */}
          <span aria-hidden className="relative h-2 min-w-16 flex-1">
            <span
              className={cn(
                'absolute inset-y-0 start-0 rounded-e-[4px]',
                lead ? 'bg-primary' : 'bg-muted-foreground/40',
              )}
              style={{ width: at(arm.rate) }}
            />
            <span
              className="bg-foreground/70 absolute top-1/2 h-0.5 -translate-y-1/2 rounded-full"
              style={{
                insetInlineStart: at(arm.interval[0]),
                width: `calc(${at(arm.interval[1])} - ${at(arm.interval[0])})`,
              }}
            />
          </span>
        </div>
      </td>
    </tr>
  )
}

function VerdictLine({
  comparison,
  armLabel,
  percent,
  count,
}: {
  comparison: Comparison
  armLabel: (arm: string) => string
  percent: Intl.NumberFormat
  count: Intl.NumberFormat
}) {
  const verdict = VERDICT[comparison.verdict]
  const Icon = verdict.icon
  const points = (value: number) =>
    `${value >= 0 ? '+' : '−'}${Math.abs(value * 100).toFixed(1)} pts`
  const against =
    comparison.against === 'holdout'
      ? 'not showing it'
      : armLabel(comparison.against).toLowerCase()
  const subject =
    comparison.arm === 'shown' ? 'Showing it' : armLabel(comparison.arm)
  return (
    <li className="flex items-start gap-2">
      <Icon
        aria-hidden
        className="text-muted-foreground mt-0.5 size-4 shrink-0"
      />
      <p className="text-pretty">
        <span className="font-medium">{verdict.label}.</span>{' '}
        <span className="text-muted-foreground">
          {subject} against {against}: {points(comparison.difference)}
          {comparison.relative !== null
            ? ` (${comparison.relative >= 0 ? '+' : '−'}${percent.format(Math.abs(comparison.relative))})`
            : ''}
          , 95% interval {points(comparison.interval[0])} to{' '}
          {points(comparison.interval[1])}.
          {comparison.moreNeeded
            ? ` About ${count.format(comparison.moreNeeded)} more exposures per arm to tell.`
            : ''}
        </span>
      </p>
    </li>
  )
}
